INSERT INTO raw_feedback (
    id, source, source_ref, raw_title, raw_content, raw_author_name,
    raw_author_contact, raw_location, category_hint, raw_metadata,
    received_at, processing_status, processed_at, created_at, updated_at
) VALUES
    ('10000000-0000-0000-0000-000000000001', 'WEBSITE', 'public-web-1001', 'Cấp căn cước công dân nhanh chóng', 'Tôi làm thủ tục cấp căn cước công dân tại bộ phận một cửa. Cán bộ hướng dẫn rõ ràng, thời gian chờ ngắn và trả kết quả đúng hẹn.', 'Nguyễn An', 'an@example.com', 'UBND phường Bến Nghé, Quận 1', 'Hành chính công', '{"channel":"cong-dich-vu-cong"}', CURRENT_TIMESTAMP - INTERVAL '7 days', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '7 days', CURRENT_TIMESTAMP - INTERVAL '7 days', CURRENT_TIMESTAMP - INTERVAL '7 days'),
    ('10000000-0000-0000-0000-000000000002', 'ZALO', 'public-zalo-1002', 'Tra cứu hồ sơ trực tuyến thuận tiện', 'Tôi tra cứu tiến độ hồ sơ trên Cổng Dịch vụ công rất dễ dàng. Thông tin cập nhật đầy đủ nên không cần đến cơ quan nhiều lần.', 'Trần Bình', NULL, 'TP. Hồ Chí Minh', 'Dịch vụ công trực tuyến', '{"channel":"zalo-oa"}', CURRENT_TIMESTAMP - INTERVAL '6 days', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '6 days', CURRENT_TIMESTAMP - INTERVAL '6 days', CURRENT_TIMESTAMP - INTERVAL '6 days'),
    ('10000000-0000-0000-0000-000000000003', 'EMAIL', 'public-email-1003', 'Hồ sơ đăng ký khai sinh chậm', 'Tôi đã nộp hồ sơ đăng ký khai sinh nhưng quá thời hạn hẹn vẫn chưa nhận được kết quả. Mong bộ phận hộ tịch kiểm tra và phản hồi sớm.', 'Lê Chi', 'chi@example.com', 'UBND phường Thảo Điền, TP. Thủ Đức', 'Hành chính công', '{"mailbox":"motcua"}', CURRENT_TIMESTAMP - INTERVAL '5 days', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '5 days', CURRENT_TIMESTAMP - INTERVAL '5 days', CURRENT_TIMESTAMP - INTERVAL '5 days'),
    ('10000000-0000-0000-0000-000000000004', 'MANUAL', 'public-manual-1004', 'Khu vực chờ làm thủ tục đất đai quá đông', 'Khu vực tiếp nhận hồ sơ đất đai rất đông, ít ghế ngồi và chưa có bảng hướng dẫn thứ tự rõ ràng. Đề nghị đơn vị cải thiện điều kiện phục vụ người dân.', 'Phạm Dũng', NULL, 'Chi nhánh Văn phòng đăng ký đất đai Quận 7', 'Đất đai - Nhà ở', NULL, CURRENT_TIMESTAMP - INTERVAL '4 days', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '4 days', CURRENT_TIMESTAMP - INTERVAL '4 days', CURRENT_TIMESTAMP - INTERVAL '4 days'),
    ('10000000-0000-0000-0000-000000000005', 'WEBSITE', 'public-web-1005', 'Nộp lệ phí trước bạ trực tuyến rõ ràng', 'Các bước nộp lệ phí trước bạ trực tuyến được hướng dẫn dễ hiểu. Tôi hoàn thành thủ tục nhanh và nhận được biên lai điện tử ngay.', 'Hoàng Em', 'em@example.com', NULL, 'Dịch vụ công trực tuyến', '{"channel":"cong-dich-vu-cong"}', CURRENT_TIMESTAMP - INTERVAL '3 days', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '3 days', CURRENT_TIMESTAMP - INTERVAL '3 days', CURRENT_TIMESTAMP - INTERVAL '3 days'),
    ('10000000-0000-0000-0000-000000000006', 'ZALO', 'public-zalo-1006', 'Cần hỗ trợ gia hạn thẻ bảo hiểm y tế', 'Tôi chưa tìm thấy hướng dẫn gia hạn thẻ bảo hiểm y tế trên cổng trực tuyến. Mong được hướng dẫn thêm các giấy tờ cần chuẩn bị.', 'Võ Giang', NULL, NULL, 'Dịch vụ công trực tuyến', NULL, CURRENT_TIMESTAMP - INTERVAL '2 days', 'NEW', NULL, CURRENT_TIMESTAMP - INTERVAL '2 days', CURRENT_TIMESTAMP - INTERVAL '2 days'),
    ('10000000-0000-0000-0000-000000000007', 'EMAIL', 'public-email-1007', 'Đèn tại lối vào bộ phận một cửa bị hỏng', 'Đèn chiếu sáng ở lối vào bộ phận một cửa bị hỏng nhiều ngày, buổi tối rất nguy hiểm cho người dân và người cao tuổi. Đề nghị xử lý khẩn cấp.', 'Bùi Hoa', 'hoa@example.com', 'UBND phường An Phú, TP. Thủ Đức', 'Hành chính công', '{"mailbox":"phan-anh-hien-truong"}', CURRENT_TIMESTAMP - INTERVAL '1 day', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '1 day', CURRENT_TIMESTAMP - INTERVAL '1 day', CURRENT_TIMESTAMP - INTERVAL '1 day'),
    ('10000000-0000-0000-0000-000000000008', 'OTHER', 'public-other-1008', 'Phản ánh trùng lặp về lịch tiếp dân', 'Nội dung phản ánh về lịch tiếp dân đã được gửi trước đó. Đề nghị hệ thống đánh dấu trùng lặp để tránh xử lý hai lần.', NULL, NULL, NULL, 'Hành chính công', NULL, CURRENT_TIMESTAMP - INTERVAL '12 hours', 'PROCESSED', CURRENT_TIMESTAMP - INTERVAL '12 hours', CURRENT_TIMESTAMP - INTERVAL '12 hours', CURRENT_TIMESTAMP - INTERVAL '12 hours'),
    ('10000000-0000-0000-0000-000000000009', 'MANUAL', 'public-manual-1009', 'Không thể đọc tệp đính kèm hồ sơ', 'Tệp đính kèm từ phiếu phản ánh không thể xử lý do định dạng không hợp lệ.', 'Đoàn Khoa', NULL, NULL, NULL, '{"import":"legacy"}', CURRENT_TIMESTAMP - INTERVAL '2 hours', 'FAILED', CURRENT_TIMESTAMP - INTERVAL '2 hours', CURRENT_TIMESTAMP - INTERVAL '2 hours', CURRENT_TIMESTAMP - INTERVAL '2 hours');

